\eqalignno{\gamma+\nu F_{m,n+1} 
&\ge\nu(E_{n+1}\cup F_{mn})+\nu(E_{n+1}\cap F_{mn})\cr&
=\nu E_{n+1}+\nu F_{mn}
\Displaycause{231Bc}
\ge\gamma-2^{-n-1}+\gamma-2\cdot 2^{-m}+2^{-n}
\Displaycause{by the choice of $E_{n+1}$ and the inductive 
hypothesis} 
=2\gamma-2\cdot 2^{-m}+2^{-n-1}.
\cr}

